const API = require('../../utils/api');Page({data:{products:[],filteredProducts:[],currentCat:'',cartCount:0,cartTotal:'0.00'},onLoad(){API.getProducts().then(products=>{const p=products.map(x=>({...x,_qty:0}));this.setData({products:p,filteredProducts:p})})},switchCat(e){const cat=e.currentTarget.dataset.cat;const list=cat?this.data.products.filter(p=>p.category===cat):this.data.products;this.setData({currentCat:cat,filteredProducts:list})},incQty(e){const id=e.currentTarget.dataset.id;const products=this.data.products.map(p=>p.productId===id?{...p,_qty:(p._qty||0)+1}:p);this.setData({products},()=>this.updateCart())},decQty(e){const id=e.currentTarget.dataset.id;const products=this.data.products.map(p=>p.productId===id&&p._qty>0?{...p,_qty:p._qty-1}:p);this.setData({products},()=>this.updateCart())},updateCart(){const items=this.data.products.filter(p=>p._qty>0);const count=items.reduce((s,p)=>s+p._qty,0);const total=items.reduce((s,p)=>s+p._qty*p.price,0);this.setData({cartCount:count,cartTotal:total.toFixed(2)})},checkout(){wx.showToast({title:'结账功能开发中',icon:'none'})},goCart(){wx.showToast({title:'购物车',icon:'none'})}})